def dec(i, t, bots, what, code, ev, verdict, key, stype='observed', why=''):
    d = {'id': f'D{i:02d}', 't': t, 'bots': bots, 'what': what, 'why': why, 'codePath': code, 'evidence': ev,
         'verdict': verdict, 'patternId': 'NEW', 'patternKey': key, 'statementType': stype}
    return d


